    /// Returns recently opened chats. This is an offline method. Returns chats in the order of last opening
    /// </summary>
    public Task<TdLib.TdApi.Objects.Chats> GetRecentlyOpenedChatsAsync(int limit = default)
    {

           using var activity =  StartCallActivity("GetRecentlyOpenedChatsAsync", typeof(GetRecentlyOpenedChats).FullName ?? "GetRecentlyOpenedChatsAsync");

           try
           {
             return client.GetRecentlyOpenedChatsAsync(limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
